package dev.riserecode;

import dev.riserecode.setting.*;
import dev.riserecode.ui.clickgui.ClickGui;
import dev.riserecode.ui.component.*;
import dev.riserecode.ui.component.setting.*;
import dev.riserecode.ui.hud.HudEditorScreen;
import net.fabricmc.fabric.api.client.gametest.v1.context.ClientGameTestContext;
import net.minecraft.client.input.*;

/** Expanded controls and resource journeys on the actual small native viewport. */
public final class UxNestedIntegrationTest {
    private static int checks;
    private static void check(boolean condition,String message){checks++;if(!condition){throw new AssertionError(message);}}
    private static void number(String name,double value){((DoubleSetting)Client.INSTANCE.getThemeManager().getSetting(name)).setValue(value);}
    private static ColorPicker picker(){return ((HudEditorScreen)net.minecraft.client.Minecraft.getInstance().gui.screen()).getControls().stream().filter(ColorPicker.class::isInstance).map(ColorPicker.class::cast).findFirst().orElseThrow();}
    private static void key(ClientGameTestContext c,int key,int modifiers){if(modifiers==0){c.getInput().pressKey(key);}else{c.runOnClient(mc->{var nav=KeyboardNavigation.auxiliary(mc.gui.screen());if(nav==null||!nav.key(new KeyEvent(key,0,modifiers))){mc.gui.screen().keyPressed(new KeyEvent(key,0,modifiers));}});}c.waitTicks(2);}
    private static void invalid(TextField field){field.setFocused(true);field.selectAll();field.charTyped(new CharacterEvent('z'));FocusedInput.commit();}
    public static void run(ClientGameTestContext c){
        c.waitFor(mc->Client.INSTANCE.isInitialized()&&Client.INSTANCE.resourcesReady()&&mc.gui.overlay()==null,1200);
        int[] original=c.computeOnClient(mc->new int[]{mc.getWindow().getScreenWidth(),mc.getWindow().getScreenHeight(),mc.options.guiScale().get()});
        c.getInput().resizeWindow(960,720);
        c.runOnClient(mc->{mc.options.guiScale().set(3);Client.INSTANCE.getThemeManager().reset();Client.INSTANCE.getClickGui().open(null);Client.INSTANCE.openHudEditor();});c.waitTicks(12);
        key(c,258,0);key(c,257,0);
        c.runOnClient(mc->{((HudEditorScreen)mc.gui.screen()).getSettingsSection().setExpanded(true);picker().setExpanded(true);});
        for(double scale:new double[]{.75,1,2}){
            c.runOnClient(mc->number("Font Scale",scale));c.waitTicks(25);
            String name=c.computeOnClient(mc->picker().getSetting().getName());
            UxAuxiliaryIntegrationTest.focus(c,name+", start, Blue, slider,");c.waitTicks(3);
            c.runOnClient(mc->{var p=picker();var view=((HudEditorScreen)mc.gui.screen()).getContextViewportBounds();var b=p.channel(3).getBounds();check(b.y()>=view.y()-.01&&b.y()+b.height()<=view.y()+view.height()+.01,"Final color channel is revealed in small viewport at font "+scale);double previous=p.speed().getBounds().y()+p.speed().getBounds().height();for(var slider:new Slider[]{p.spacing(),p.channel(0),p.channel(1),p.channel(2),p.channel(3)}){var row=slider.getBounds();check(row.y()>=previous+4.9&&row.height()>=SettingMetrics.height(slider,0)-.01,"Expanded color child reserves label value validation and track at font "+scale);previous=row.y()+row.height();}int before=p.getSetting().getValue();var event=new MouseButtonEvent(b.x()+b.width()-8,b.y()+b.height()-5,new MouseButtonInfo(0,0));mc.gui.screen().mouseClicked(event,false);mc.gui.screen().mouseReleased(event);check((p.getSetting().getValue()&255)>240,"Partially clipped parent forwards visible Blue track at font "+scale);p.getSetting().setValue(before);});
            c.takeScreenshot("ux5-expanded-color-blue-font"+scale);
        }
        c.runOnClient(mc->{var hud=(HudEditorScreen)mc.gui.screen();hud.getSelected().layout().position(.123456789123,hud.getSelected().layout().y());});c.waitTicks(3);
        c.runOnClient(mc->{var hud=(HudEditorScreen)mc.gui.screen();var slider=hud.getControls().stream().filter(v->v instanceof Slider n&&n.name().equals("Position X")).map(Slider.class::cast).findFirst().orElseThrow();check(slider.input().getValue().equals("0.123"),"Idle normalized coordinate uses concise step-aware format");slider.beginEditing();check(slider.input().getValue().equals("0.123456789123"),"Precise edit exposes exact stored coordinate");FocusedInput.commit();check(hud.getSelected().layout().x()==.123456789123,"Unchanged numeric commit does not quantize model");});
        c.runOnClient(mc->{var p=picker();var setting=p.getSetting();setting.setMode(ColorSetting.Mode.THEME);int before=setting.getValue();invalid(p.getHexField());check(p.getHexField().getValue().equals("z")&&!p.getHexField().validation().isEmpty(),"Invalid start hex survives blur");p.selectEndpoint(true);invalid(p.getHexField());p.selectEndpoint(false);check(p.getHexField().getValue().equals("z")&&!p.getHexField().validation().isEmpty(),"Endpoint switch preserves invalid start draft");p.getHexField().setFocused(true);FocusedInput.cancel();check(setting.getValue()==before&&setting.getMode()==ColorSetting.Mode.THEME&&p.getHexField().validation().isEmpty(),"Escape restores color and mode baseline");p.selectEndpoint(true);check(p.getHexField().getValue().equals("z")&&!p.getHexField().validation().isEmpty(),"Invalid end draft survives other endpoint cancellation");p.channel(3).adjust(1);int replacement=setting.getSecondary();check(p.getHexField().validation().isEmpty()&&p.getHexField().getValue().equals(ColorSetting.hex(replacement)),"Channel replacement clears invalid end draft");p.getHexField().setFocused(true);FocusedInput.cancel();check(setting.getSecondary()==replacement&&setting.getMode()==ColorSetting.Mode.GRADIENT,"Escape retains explicit channel replacement baseline");check(p.channel(3).input().accessibleName().contains(setting.getName()+", end, Blue"),"Nested channel identity includes owner and endpoint");mc.gui.screen().onClose();var glass=Client.INSTANCE.getModuleManager().getByClass(dev.riserecode.module.modules.GlassModule.class).orElseThrow();mc.gui.setScreen(new GlassEditorScreen(glass,Client.INSTANCE.getClickGui()));});c.waitTicks(25);
        c.runOnClient(mc->{var p=((GlassEditorScreen)mc.gui.screen()).getControls().stream().filter(ColorPicker.class::isInstance).map(ColorPicker.class::cast).findFirst().orElseThrow();p.getSetting().setValue(p.getSetting().getValue()&0xFFFFFF00);p.setExpanded(true);});c.waitTicks(25);
        String glassName=c.computeOnClient(mc->((GlassEditorScreen)mc.gui.screen()).getControls().stream().filter(ColorPicker.class::isInstance).map(ColorPicker.class::cast).findFirst().orElseThrow().getSetting().getName());
        UxAuxiliaryIntegrationTest.focus(c,glassName+", start, Blue, slider,");c.waitTicks(3);
        c.runOnClient(mc->{var p=((GlassEditorScreen)mc.gui.screen()).getControls().stream().filter(ColorPicker.class::isInstance).map(ColorPicker.class::cast).findFirst().orElseThrow();var b=p.channel(3).getBounds();var event=new MouseButtonEvent(b.x()+b.width()-8,b.y()+b.height()-5,new MouseButtonInfo(0,0));mc.gui.screen().mouseClicked(event,false);mc.gui.screen().mouseReleased(event);check((p.getSetting().getValue()&255)>240,"Glass forwards visible channel click inside clipped expanded parent");});c.takeScreenshot("ux5-glass-expanded-blue-font2");
        c.runOnClient(mc->((GlassEditorScreen)mc.gui.screen()).showPreview(true));c.waitTicks(3);c.takeScreenshot("ux6-glass-full-preview-font2");
        c.runOnClient(mc->{mc.gui.screen().onClose();number("Window Width",360);number("Window Height",240);number("Content Padding",20);Client.INSTANCE.getClickGui().selectPage(ClickGui.Page.COSMETICS);var editor=Client.INSTANCE.getClickGui().getCosmeticsEditor();var def=Client.INSTANCE.getCosmetics().library().definitions().stream().filter(d->Client.INSTANCE.getCosmetics().library().available(d)).findFirst().orElseThrow();editor.select(def.id());editor.buttons().stream().filter(b->b.label().equals("Edit")).findFirst().orElseThrow().activate();editor.getItemSection().setExpanded(true);editor.getControls().stream().filter(ColorPicker.class::isInstance).map(ColorPicker.class::cast).forEach(p->{p.getSetting().setValue(p.getSetting().getValue()&0xFFFFFF00);p.setExpanded(true);});});c.waitTicks(25);
        UxAuxiliaryIntegrationTest.focus(c,"Primary color, start, Blue, slider,");c.waitTicks(3);
        c.runOnClient(mc->{var e=Client.INSTANCE.getClickGui().getCosmeticsEditor();var p=e.getControls().stream().filter(ColorPicker.class::isInstance).map(ColorPicker.class::cast).findFirst().orElseThrow();var b=p.channel(3).getBounds();e.mouseClicked(b.x()+b.width()-8,b.y()+b.height()-5,0);e.mouseReleased(b.x()+b.width()-8,b.y()+b.height()-5,0);check((p.getSetting().getValue()&255)>240,"Compact cosmetic editor forwards clipped expanded channel click");check(e.previewBounds().width()==0,"Small cosmetic editing dedicates space to form");});c.takeScreenshot("ux5-cosmetic-expanded-blue-font2");
        c.runOnClient(mc->{Client.INSTANCE.getClickGui().getCosmeticsEditor().discard();Client.INSTANCE.getClickGui().selectPage(ClickGui.Page.APPEARANCE);Client.INSTANCE.getClickGui().getSearchField().setValue("Primary Accent");((ColorPicker)Client.INSTANCE.getClickGui().getThemeEditor().getControl("Primary Accent")).setExpanded(true);});c.waitTicks(25);
        UxAuxiliaryIntegrationTest.focus(c,"Primary Accent, start, Blue, slider,");c.takeScreenshot("ux5-appearance-expanded-blue-font2");
        c.runOnClient(mc->{Client.INSTANCE.getClickGui().getSearchField().setValue("");Client.INSTANCE.getClickGui().selectPage(ClickGui.Page.RESOURCES);number("Window Width",360);number("Window Height",240);number("Content Padding",20);});c.waitTicks(25);
        c.runOnClient(mc->{check(mc.gui.screen().width==320&&mc.gui.screen().height==240,"Resource journey uses real native 320x240 viewport");var library=Client.INSTANCE.getResourcesManager().library();check(library.progress().ready()&&library.catalog().entries().size()>=600,"Complete offline resource catalog loaded");Client.INSTANCE.getClickGui().getKeyboardNavigation().pointerUsed();});
        for(int i=0;i<30;i++){key(c,258,1);if(c.computeOnClient(mc->Client.INSTANCE.getClickGui().focusedControlLabel().startsWith("Cancel, button"))){break;}}for(int i=0;i<8;i++){key(c,258,1);if(c.computeOnClient(mc->Client.INSTANCE.getClickGui().focusedControlLabel().startsWith("Resource, "))){break;}}
        String last=c.computeOnClient(mc->Client.INSTANCE.getResourcesManager().library().catalog().entries().getLast().name());
        c.runOnClient(mc->{var gui=Client.INSTANCE.getClickGui();check(gui.focusedControlLabel().startsWith("Resource, "+last+","),"Backward traversal reaches final catalog card");check(gui.getResourcesEditor().scrollPosition()>0,"Logical card focus reveals bottom of long catalog");});c.takeScreenshot("ux5-resources-last-card-font2");
        key(c,262,0);c.runOnClient(mc->check(Client.INSTANCE.getClickGui().focusedControlLabel().startsWith("Back from "+last),"Opening details moves focus to contextual Back"));c.takeScreenshot("ux5-resources-detail-font2");
        c.runOnClient(mc->check(Client.INSTANCE.getClickGui().getResourcesEditor().getBodyBounds().height()>90,"Resource details reclaim search and filter space in minimum viewport"));
        key(c,267,0);c.waitTicks(8);c.runOnClient(mc->{var e=Client.INSTANCE.getClickGui().getResourcesEditor();check(e.scrollPosition()<=e.maximumScroll(),"Font-aware description scrolling remains bounded");});c.takeScreenshot("ux5-resources-detail-scrolled-font2");key(c,256,0);
        c.runOnClient(mc->{check(Client.INSTANCE.getClickGui().focusedControlLabel().startsWith("Resource, "+last+","),"Details Escape restores original card identity");var editor=Client.INSTANCE.getClickGui().getResourcesEditor();editor.resetDraft();var catalog=Client.INSTANCE.getResourcesManager().library().catalog();for(int i=0;i<12;i++){editor.toggle(catalog.entries().get(i));}editor.showSelected();});c.waitTicks(5);
        String selected=c.computeOnClient(mc->Client.INSTANCE.getResourcesManager().library().catalog().entries().get(0).name());
        UxAuxiliaryIntegrationTest.focus(c,selected+", resource details");c.runOnClient(mc->check(Client.INSTANCE.getClickGui().getResourcesEditor().scrollPosition()>0,"Selected list deep keyboard focus reveals bottom rows"));c.takeScreenshot("ux5-resources-selected-bottom-font2");
        key(c,257,0);key(c,256,0);c.runOnClient(mc->check(Client.INSTANCE.getClickGui().focusedControlLabel().startsWith(selected+", resource details"),"Selected details Back retains row identity"));
        key(c,265,2);c.runOnClient(mc->{var editor=Client.INSTANCE.getClickGui().getResourcesEditor();var id=Client.INSTANCE.getResourcesManager().library().catalog().entries().get(0).id();check(editor.draft().selected().indexOf(id)==10,"Ctrl Up reorders selected resource");check(Client.INSTANCE.getClickGui().focusedControlLabel().startsWith(selected+", resource details"),"Reorder preserves focused resource identity");});
        UxAuxiliaryIntegrationTest.focus(c,selected+", remove resource");key(c,257,0);c.runOnClient(mc->{check(Client.INSTANCE.getClickGui().getResourcesEditor().draft().selected().size()==11,"Keyboard removal updates selection");check(Client.INSTANCE.getClickGui().focusedControlLabel().contains("resource details"),"Removal focuses neighboring row");Client.INSTANCE.getClickGui().getResourcesEditor().getToolsButton().activate();Client.INSTANCE.getClickGui().getResourcesEditor().getToolsSection().setExpanded(true);});c.waitTicks(25);
        UxAuxiliaryIntegrationTest.focus(c,"Vanilla Tweaks, button");c.runOnClient(mc->{var e=Client.INSTANCE.getClickGui().getResourcesEditor();check(e.maximumScroll()>0&&e.scrollPosition()>0,"Short Tools view scrolls to final provider action");});c.takeScreenshot("ux5-resources-tools-bottom-font2");
        key(c,256,0);UxAuxiliaryIntegrationTest.focus(c,"All categories, button");key(c,257,0);c.waitTicks(12);
        String lastCategory=c.computeOnClient(mc->{var names=new java.util.LinkedHashSet<String>();for(var entry:Client.INSTANCE.getResourcesManager().library().catalog().entries()){names.add(entry.category().split(" / ")[0]);names.add(entry.category());}return names.getLast();});
        UxAuxiliaryIntegrationTest.focus(c,lastCategory+", button");c.runOnClient(mc->check(Client.INSTANCE.getClickGui().getResourcesEditor().scrollPosition()>0,"Category keyboard traversal reveals the final category"));c.takeScreenshot("ux5-resource-final-category-font2");key(c,257,0);
        c.runOnClient(mc->{check(Client.INSTANCE.getClickGui().focusedControlLabel().startsWith("Resource, "),"Category selection focuses matching resource");Client.INSTANCE.getResourcesManager().library().start(true);});c.waitFor(mc->!Client.INSTANCE.getResourcesManager().library().progress().running(),600);c.waitTicks(5);
        c.runOnClient(mc->{var progress=Client.INSTANCE.getResourcesManager().library().progress();check(!progress.ready()&&!progress.failures().isEmpty()&&progress.phase().contains("Retry"),"Offline refresh failure offers retry and blocks non-empty apply");});c.takeScreenshot("ux5-resources-refresh-failure-font2");
        c.runOnClient(mc->{Client.INSTANCE.getClickGui().getResourcesEditor().discard();Client.INSTANCE.getThemeManager().reset();mc.gui.setScreen(null);});c.getInput().resizeWindow(original[0],original[1]);c.runOnClient(mc->mc.options.guiScale().set(original[2]));c.waitTicks(5);
        Client.INSTANCE.getLogger().info("UX nested control and Resources checks passed: {}",checks);
    }
}
